 useEffect(()=>{if(!selectedPlace||!db)return;let live=true;const load=async()=>{const {data}=await db.from('nearby_place_reviews').select('rating,review,created_at,user_id').eq('provider_id',selectedPlace.provider_id).order('created_at',{ascending:false}).limit(30);if(live)PR(data||[]);};void load();if(selectedPlace.commons&&!selectedPlace.photo_url){const raw=selectedPlace.commons.replace(/^File:/i,'').trim();const url='https://commons.wikimedia.org/w/api.php?action=query&titles='+encodeURIComponent('File:'+raw)+'&prop=imageinfo&iiprop=url|extmetadata&iiurlwidth=900&format=json&origin=*';fetch(url).then(r=>r.json()).then(data=>{const page=Object.values(data?.query?.pages||{})[0] as any;const info=page?.imageinfo?.[0];if(live&&info?.thumburl){const clean=(v:string)=>String(v||'').replace(/<[^>]*>/g,' ').replace(/&nbsp;/g,' ').trim();SP(old=>old?.provider_id===selectedPlace.provider_id?{...old,photo_url:info.thumburl,photo_credit:clean(info.extmetadata?.Artist?.value)||'Wikimedia Commons contributor',photo_license:clean(info.extmetadata?.LicenseShortName?.value)||'See source page'}:old);}}).catch(()=>{});}return()=>{live=false};},[selectedPlace?.provider_id]);
 useEffect(()=>{if(!session||!db)return;const channel=db.channel('nearby-live-activity-'+session.user.id).on('postgres_changes',{event:'INSERT',schema:'public',table:'nearby_activity'},()=>{void loadActivity()}).subscribe();return()=>{db.removeChannel(channel)}},[session]);
 async function loadFriendRequests(){if(!db||!session)return;const {data,error}=await db.from('follows').select('follower_id,created_at').eq('following_id',session.user.id).eq('status','pending').order('created_at',{ascending:false}).limit(30);if(error)return;const ids=(data||[]).map((x:any)=>x.follower_id);if(!ids.length){IRq([]);return;}const {data:people}=await db.from('profiles').select('id,username,display_name,avatar_url').in('id',ids);IRq((data||[]).map((x:any)=>({...x,profile:(people||[]).find((p:any)=>p.id===x.follower_id)})).filter((x:any)=>x.profile));}
 async function loadLocationRequests(){
  if(!db||!session)return;
  await db.from('nearby_location_requests').update({status:'expired'}).eq('status','pending').lte('expires_at',new Date().toISOString()).or('sender_id.eq.'+session.user.id+',recipient_id.eq.'+session.user.id);
  const [{data:incoming},{data:outgoing}]=await Promise.all([
   db.from('nearby_location_requests').select('*').eq('recipient_id',session.user.id).in('status',['pending','accepted','declined','expired']).order('created_at',{ascending:false}).limit(30),
   db.from('nearby_location_requests').select('*').eq('sender_id',session.user.id).in('status',['pending','accepted','declined','cancelled','expired']).order('created_at',{ascending:false}).limit(30)
  ]);
  const rows=[...(incoming||[]),...(outgoing||[])],ids=[...new Set(rows.flatMap((x:any)=>[x.sender_id,x.recipient_id]).filter((id:string)=>id!==session.user.id))];
  const {data:profiles}=ids.length?await db.from('profiles').select('id,username,display_name,avatar_url').in('id',ids):{data:[]};
  const attach=(x:any)=>({...x,person:(profiles||[]).find((p:any)=>p.id===(x.sender_id===session.user.id?x.recipient_id:x.sender_id))});
  LI((incoming||[]).map(attach));LO((outgoing||[]).map(attach));
 }
 async function loadLocationConnections(){
  if(!db||!session)return;
  const {data,error}=await db.from('nearby_location_connections').select('id,user_a,user_b,user_a_sharing,user_b_sharing,user_a_expires_at,user_b_expires_at').or('user_a.eq.'+session.user.id+',user_b.eq.'+session.user.id);
  if(error)return;
  const rows=(data||[]).filter((x:any)=>{const expiry=x.user_a===session.user.id?x.user_a_expires_at:x.user_b_expires_at;return !expiry||new Date(expiry).getTime()>Date.now();});
  const ids=rows.map((x:any)=>x.user_a===session.user.id?x.user_b:x.user_a);
  if(!ids.length){AC([]);return;}
  const {data:profiles}=await db.from('profiles').select('id,username,display_name,avatar_url').in('id',ids);
  AC(rows.map((x:any)=>{const other=x.user_a===session.user.id?x.user_b:x.user_a;return {...x,person:(profiles||[]).find((p:any)=>p.id===other),ownSharing:x.user_a===session.user.id?x.user_a_sharing:x.user_b_sharing,otherSharing:x.user_a===session.user.id?x.user_b_sharing:x.user_a_sharing};}).filter((x:any)=>x.person));
 }
 async function requestMutualLocation(p:any){
  if(!db||!session)return;
  const {data:existing}=await db.from('nearby_location_requests').select('id,status').eq('sender_id',session.user.id).eq('recipient_id',p.id).eq('status','pending').maybeSingle();
  if(existing){N('Location request is already pending.');return;}
  const expires=new Date(Date.now()+48*60*60*1000).toISOString();
  const {error}=await db.from('nearby_location_requests').insert({sender_id:session.user.id,recipient_id:p.id,status:'pending',expires_at:expires});
  if(error)N(error.code==='23505'?'A request is already pending.':error.message.includes('row-level security')?'Location requests are available only between accepted mutual connections.':error.message);
  else{N('Live-location request sent. They must accept before either location is shared.');await loadLocationRequests();}
 }
 async function decideLocationRequest(id:string,accept:boolean){
  const {error}=await db.from('nearby_location_requests').update({status:accept?'accepted':'declined',responded_at:new Date().toISOString()}).eq('id',id).eq('recipient_id',session.user.id).eq('status','pending');
  if(error)N(error.message);else{N(accept?'Location connection accepted. Both people can now enable their own sharing.':'Location request declined.');await loadLocationRequests();}
 }
 async function cancelLocationRequest(id:string){
  const {error}=await db.from('nearby_location_requests').update({status:'cancelled'}).eq('id',id).eq('sender_id',session.user.id).eq('status','pending');
  if(error)N(error.message);else{N('Location request cancelled.');await loadLocationRequests();}
 }
 async function searchNearbyPeople(){const term=peopleQuery.trim().replace(/^@/,'').toLowerCase();if(!term){PRs([]);return;}PB(true);const {data,error}=await db.rpc('find_profile_exact',{search_username:term});if(error)N(error.message);else{const people=(data||[]).filter((p:any)=>p.id!==session.user.id);PRs(people.map((p:any)=>({...p,canRequestLocation:true})));}PB(false);}
 async function requestNearbyConnection(p:any){const {data:existing}=await db.from('follows').select('status').eq('follower_id',session.user.id).eq('following_id',p.id).maybeSingle();if(existing){N(existing.status==='accepted'?'You are already connected.':'Connection request already sent.');return;}const {error}=await db.from('follows').insert({follower_id:session.user.id,following_id:p.id,status:'pending'});if(error)N(error.code==='23505'?'Connection request already exists.':error.message);else{N('Connection request sent.');PRs(old=>old.filter(x=>x.id!==p.id));}}
 async function decideNearbyRequest(id:string,accept:boolean){const {error}=await db.from('follows').update({status:accept?'accepted':'rejected'}).eq('follower_id',id).eq('following_id',session.user.id).eq('status','pending');if(error)N(error.message);else{N(accept?'Connection accepted.':'Request declined.');await loadFriendRequests();}}
 const visiblePlaces=useMemo(()=>filter==='all'||filter==='places'?places:filter==='saved'?savedPlaces:places.filter(p=>p.category===filter),[places,savedPlaces,filter]);
