 function distanceTo(person:NearbyPersonPoint){const me=livePeople.find(p=>p.is_self);if(!me)return 'Distance unavailable';const rad=(v:number)=>v*Math.PI/180;const dLat=rad(person.latitude-me.latitude),dLon=rad(person.longitude-me.longitude);const a=Math.sin(dLat/2)**2+Math.cos(rad(me.latitude))*Math.cos(rad(person.latitude))*Math.sin(dLon/2)**2;const km=6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a));return km<1?Math.round(km*1000)+' m':km.toFixed(1)+' km';}
